using System;using System.Collections.Generic;using System.Drawing;using System.IO;using System.Reflection;using System.Threading;using System.Windows.Forms;using System.Web.Script.Serialization;using CodexWatchdog;
class ScopeAlarmUiTests
{
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer();static object F(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,a);}static void Check(bool b,string m){if(!b)throw new Exception(m);}static bool Ring(MainForm f){return ((AlarmSound)F(f,"alarm")).IsPlaying;}static void Poll(MainForm f){Call(f,"Poll",new object[]{null});Application.DoEvents();}
 static void Record(string p,string type,object payload){File.AppendAllText(p,Json.Serialize(new{timestamp=DateTime.UtcNow.ToString("o"),type=type,payload=payload})+"\n");}static void Start(string p,string turn){Record(p,"event_msg",new{type="task_started",turn_id=turn});}static void Ask(string p,string id){Record(p,"response_item",new{type="function_call",name="request_user_input_async",call_id=id});}static void Answer(string p,string id){Record(p,"response_item",new{type="function_call_output",call_id=id,output=Json.Serialize(new{answers=new{q="yes"}})});}static void Scope(MainForm f,WatchSettings s,bool all,params string[] ids){s.MonitorAllSources=all;s.SelectedSourceIds=new List<string>(ids);Call(f,"ApplySettings");}
 [STAThread]static int Main(){string home=Path.Combine(Path.GetTempPath(),"watchdog-scope-"+Guid.NewGuid().ToString("N"));try{Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string day=Path.Combine(home,"sessions","2026","10","25");Directory.CreateDirectory(day);var files=new Dictionary<string,string>();foreach(string id in new[]{"a","b","c"}){string p=Path.Combine(day,id+".jsonl");files[id]=p;Record(p,"session_meta",new{id=id,originator="Codex Desktop",source="vscode"});Start(p,"t-"+id);}var s=new WatchSettings{VolumePercent=0,StartWithWindows=false,MonitorAllSources=false,SelectedSourceIds=new List<string>{"a","b"}};using(var f=new MainForm(s,false,home,()=>true,"",x=>true)){
 f.Location=new Point(-20000,-20000);f.Show();Application.DoEvents();var timer=(System.Threading.Timer)F(f,"pollTimer");timer.Change(Timeout.Infinite,Timeout.Infinite);while((int)F(f,"polling")!=0)Thread.Sleep(10);Application.DoEvents();((System.Windows.Forms.Timer)F(f,"displayTimer")).Stop();Poll(f);
 Record(files["c"],"event_msg",new{type="task_complete",turn_id="t-c"});Ask(files["c"],"excluded-q");Poll(f);Check(!Ring(f),"excluded patrol completion/question must stay quiet");
 Ask(files["a"],"a-q");Poll(f);Check(Ring(f)&&f.AccessibleDescription.Contains("待回答"),"selected async question must ring immediately while work continues");Check(((List<MonitorSnapshot>)F(f,"latest")).Find(x=>x.SourceId=="a").IsGenerating,"async question must not fabricate stopping");Answer(files["a"],"a-q");Poll(f);Check(!Ring(f),"answered async question must stop ringing");
 Ask(files["a"],"a-q2");Poll(f);Check(Ring(f),"new selected question rings");Scope(f,s,false,"b");Check(!Ring(f),"unchecking source immediately revokes pending alert");Scope(f,s,false);Check(!Ring(f)&&f.AccessibleDescription.Contains("未选择"),"none means no monitored chats");
 Scope(f,s,true);Poll(f);Check(!Ring(f),"all mode attaching stopped patrol must quietly baseline");Start(files["c"],"patrol-new");Ask(files["c"],"patrol-q");Poll(f);Check(Ring(f),"all includes patrol and new patrol question rings");Answer(files["c"],"patrol-q");Poll(f);Check(!Ring(f),"patrol answer clears alarm");
 Scope(f,s,false,"b");Start(files["c"],"queued-patrol");Ask(files["c"],"queued-old-q");Call(f,"Poll",new object[]{null}); // Queue old scope result without pumping.
 Scope(f,s,false,"b","c");Application.DoEvents();Check(!Ring(f),"old queued scope package must not replay newly selected patrol question");Poll(f);Check(!Ring(f),"first fresh selected snapshot must establish quiet baseline");Ask(files["c"],"fresh-new-q");Poll(f);Check(Ring(f),"genuinely new question after fresh scope baseline must ring");Call(f,"Confirm");Check(!Ring(f),"confirm stops real playback");
 Scope(f,s,false,"b");string newest=Path.Combine(day,"d.jsonl");Record(newest,"session_meta",new{id="d",originator="Codex Desktop",source="vscode"});Start(newest,"d-turn");Ask(newest,"d-old-q");
 object reader=F(f,"source");reader.GetType().GetField("discoveryUtc",BindingFlags.NonPublic|BindingFlags.Instance).SetValue(reader,DateTime.MinValue);
 Call(f,"Poll",new object[]{null});Scope(f,s,true);Application.DoEvents();Check(!Ring(f),"all scope must not replay old queued first-discovered source");Poll(f);Check(!Ring(f),"unknown source gets fresh quiet all-scope baseline");Ask(newest,"d-fresh-q");Poll(f);Check(Ring(f),"new unknown-source question after all baseline rings");Call(f,"Confirm");f.Close();}
 Console.WriteLine("PASS: actual isolated source/MainForm scoped alarms, async answer clearing, none/all patrol inclusion, stale queued scope discard and new live question");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}finally{string full=Path.GetFullPath(home),temp=Path.GetFullPath(Path.GetTempPath()).TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar;if(full.StartsWith(temp,StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(full).StartsWith("watchdog-scope-",StringComparison.Ordinal)&&Directory.Exists(full))Directory.Delete(full,true);}}
}
